// js/systems/aventura.js
// Aventura mode — solo/small-group top-down dungeon, tactical-pause combat
// rpg_registry { is_aventura: true, theme_json.dungeon_data } + characters + skills

// ─────────────────────────────────────────────────────────────────────────────
// STATE
// ─────────────────────────────────────────────────────────────────────────────

var AVT_STATE: any = {
  rpgId: null,
  rpg: null,
  chars: [],
  skills: [],
  dungeon: null,           // { tiles[][], w, h, rooms[] }
  entidades: [],           // [{ id, nome, x, y, hp, hpMax, tipo, cor, pacienciaSecs, deteccaoRaio, isBoss }]
  batalhas: [],           // Array of active combat objects (multiple simultaneous combats)
  globalLog: [],           // Log de eventos fora de combate (perseguição, entrada em fase, etc.)
  batalhaAutoSuspensa: false,
  _jogoAutoSuspenso: false,       // pause automático por inatividade de todos os jogadores
  _jogoAutoSuspensoPausadoEm: 0,
  alvoSelecionado: null,   // entId do alvo selecionado pelo clique no canvas
  _fleeTracker: {},        // { entId: { pursuing, prevDist } }
  _primeiroAtaqueAlvo: null,      // legado — mantido para compat com avtCombateEncerrar
  _primeiroAtaqueAberto: false,   // skill picker de primeiro ataque está visível
  _primeiroAtaqueModoAlvo: null,  // { skId, atacante } — aguardando clique no alvo (desktop)
  mestreReposicionando: null, // entId being repositioned by master
  canvas: null,
  ctx: null,
  camera: { x: 0, y: 0, zoom: 1 },
  animFrame: null,
  _pendingTimeouts: [],
  _resizeObs: null,
  // GM / master
  isMestre: false,
  mestreComoJogador: false, // mestre alternou para experiência de jogador
  mestreAtivo: false,      // mestre em modo controle total (pode mover todos os personagens)
  npcIaAtiva: true,
  npcControlando: null,
  mestreVisaoGeral: false,
  mestrePainelAba: 'modo',
  // player assignment
  myCharNome: null,        // nome do personagem vinculado ao usuário atual
  membros: [],             // rpg_members carregados (para atribuição)
  // patience timers (per enemy)
  npcTimers: {},           // { entId: { patience, maxPatience, ativo, isPursuing, targetId, pursuitStepTimer, inactionTimer } }
  _npcLastTick: {},        // dedup: { entId: tick } — evita reprocessar mesmo NPC no mesmo tick de 2s
  _lastFrameTs: 0,
  _oocCooldowns: {},       // { 'charId_skillId': expiryTimestamp } — cooldowns fora de combate
  _oocStatusEffects: [],   // [{ entId, ef, lastTickAt }] — efeitos ativos fora de combate
  _modoTeleporte: null,    // { entId } quando modo de teleporte está ativo
  colisaoJogJog: false,    // Jogadores bloqueiam outros jogadores
  colisaoJogNpc: false,    // Jogadores bloqueiam NPCs e vice-versa
  _convitesCombate: {},    // { charId: { batId, expiry } } — convites de combate pendentes
  _inimigosIgnorados: [], // IDs de inimigos cujo convite de perseguição foi ignorado pelo jogador
  // character editor
  charEditorId: null,
  charEditorTab: 'attrs',
  // appearance / animation rendering (token sprites)
  aparencias: {},   // entId -> { parts, animations, partImgs: {key: Image}, loaded }
  entAnim: {},      // entId -> { state, stateStart, lastX, lastY, walkUntil, attackUntil, facing }
  _criando: {
    nome: '', cor: '#c8a84b', cor2: '#4fa3d1', icone: 'sword',
    personagens: [], importCampanhaId: null,
    mapa: null,            // dungeon object chosen in step 3
    mapaOpcao: null,       // 'procedural'|'editor'|'json'|'claude'|'fase'
    faseId: null,          // selected fase id (opção 'fase')
    etapa: 0,
    _modoEscolha: null     // 'completa' | 'manual'
  },
  _novaFaseWizard: null,   // wizard state for creating extra phases
  invocacoes_ativas: [],   // [{ id, invocacao_def, dono_char_nome, hp_atual, hpMax, iniciativa, _turnosRestantes, _cooldowns }]
  _modoPortaPlacement: false, // when true, next map click sets door position
  _faseStack: [],          // trilha de retorno entre fases (ids; topo = fase anterior)
  _faseSnapshots: {},      // estado vivo por fase: { [faseId]: { dungeon, entidades, npcTimers, tileset..., hue } }
  itemCatalog: [],         // item_catalog loaded for this adventure
  _bausPreDungeon: [],     // chests prepared before dungeon is loaded
  _itensCharSel: '',       // selected char in itens tab
  _itensDarSel: '',        // selected item id to give
  _itensDarQty: 1,         // quantity to give
  _itensFiltroTipo: '',    // catalog filter in itens tab
  _ppEquipOpen: false,     // player panel equipment section open
  _menuJogadorAberto: false, // true quando menu do personagem ou painel do mestre está visível
  _pcAlvoIdx: 0,           // índice do inimigo selecionado pelas setinhas no PC
  _ultimaVerifProxGlobal: 0 // throttle para verificação periódica de proximidade
};


// ── SYNC HELPERS (anti-dessincronização) ───────────────────────────────────
// Sequência monotônica de movimento por entidade, para descartar pacotes
// avt_token_move que cheguem fora de ordem (sub-célula antiga depois do canônico).
window._avtTokenSeq = window._avtTokenSeq || Object.create(null);

// Eventos de jogo escopados por fase: o payload ganha `faseId` na emissão e os
// handlers descartam mensagens de outra fase (FIX F2 — antes, matar o boss numa
// fase escondia o boss homônimo das outras, abria baús alheios, etc., porque os
// IDs procedurais se repetem entre fases e os handlers não eram isolados).
const _AVT_EVENTOS_DE_FASE = new Set([
  'avt_token_move', 'avt_npc_morreu', 'avt_npc_respawn', 'avt_npc_perseguindo',
  'avt_combate_inicio', 'avt_batalha_update', 'avt_combate_fim', 'avt_combate_join',
  'avt_convite_combate', 'avt_bau_aberto', 'avt_obj_spawn', 'avt_obj_pickup',
  'avt_skill_anim', 'avt_attack_anim', 'avt_efeito_anim_start', 'avt_efeito_anim_stop',
  'avt_dano_visual', 'avt_dano_visual_batch', 'avt_rastro_marcar', 'avt_entidade_nova',
]);

// Helper central de broadcast para Modo Aventura.
// Usa RTNet (P2P + fallback Supabase) quando disponível; caso contrário cai no
// realtimeBroadcast original. Toda chamada avt_* deve passar por aqui.
function _avtBroadcast<K extends AvtEventName>(tipo: K, payload?: AvtPayloadMap[K]) {
  try {
    if (payload && typeof payload === 'object' && !Array.isArray(payload)
        && payload.faseId == null && _AVT_EVENTOS_DE_FASE.has(tipo)) {
      payload = Object.assign({}, payload, { faseId: (AVT_STATE && (AVT_STATE as any)._faseAtualId) || 'principal' });
    }
    if (typeof RTNet !== 'undefined' && RTNet.initialized) {
      RTNet.broadcast(tipo, payload);
    } else if (typeof realtimeBroadcast === 'function') {
      realtimeBroadcast(tipo, payload);
    }
  } catch(e) {
    try { console.warn('[AVT] _avtBroadcast falhou:', tipo, e); } catch(_) {}
  }
}
window._avtBroadcast = _avtBroadcast;

// Variante restrita a WebRTC — nunca usa Supabase broadcast.
// Usada pela IA dos NPCs; estado autoritativo chega via npc_state (Postgres Changes).
function _avtBroadcastNpc(tipo: any, payload: any) {
  try {
    if (typeof RTNet !== 'undefined' && RTNet.initialized) {
      RTNet.broadcastP2POnly(tipo, payload);
    }
  } catch(e) {
    try { console.warn('[AVT] _avtBroadcastNpc falhou:', tipo, e); } catch(_) {}
  }
}
window._avtBroadcastNpc = _avtBroadcastNpc;

function _avtBcastTokenMove(payload: any){
  try{
    if(!payload) return;
    const nome = payload.nome;
    if(nome){
      const sk = _avtSeqKey(nome);
      const next = ((window._avtTokenSeq[sk] || 0) + 1) >>> 0;
      window._avtTokenSeq[sk] = next;
      payload = Object.assign({}, payload, { seq: next, ts: Date.now() });
    }
    // Escopo por fase: jogadores em fases diferentes não interferem uns nos outros.
    if (payload.faseId == null) payload = Object.assign({}, payload, { faseId: (AVT_STATE as any)._faseAtualId || 'principal' });
    _avtBroadcast('avt_token_move', payload);
  }catch(e){
    try{ console.warn('[AVT] _avtBcastTokenMove falhou:', e); }catch(_){}
  }
}
window._avtBcastTokenMove = _avtBcastTokenMove;

// ── MOVIMENTO AUTORITATIVO: predição local + reconciliação por sequência ─────
// Em P2P não-host, cada passo do próprio personagem recebe um `seq` monotônico,
// é aplicado localmente (predição) e enviado IMEDIATAMENTE ao host. O host valida
// (colisão/tile) e ecoa o último `seq` processado (ackSeq) no tick autoritativo;
// o cliente então descarta os inputs confirmados e só reconcilia contra a posição
// do host quando não há mais inputs em voo (ver avtReceberStateTick). Isso elimina
// o "vai e volta" porque o cliente nunca briga com posições atrasadas do host.
// Limite do buffer de inputs pendentes para evitar crescimento sob desconexão.
const _AVT_MAX_PENDING_INPUTS = 32;

// Registra input local com seq + buffer e envia ao host. Retorna true se enviou via
// move_input (P2P não-host autoritativo); false quando o chamador deve usar broadcast
// direto (host local ou fallback Supabase).
function _avtEnviarMoveInput(ent: any, nx: any, ny: any){
  try{
    if (typeof RTNet === 'undefined' || !RTNet.initialized || RTNet.isHost() || RTNet.mode === 'supabase') return false;
    if (!ent) return false;
    if (!Array.isArray(ent._pendingInputs)) ent._pendingInputs = [];
    const seq = ((ent._moveSeq || 0) + 1) >>> 0;
    ent._moveSeq = seq;
    ent._pendingInputs.push({ seq, nx, ny });
    if (ent._pendingInputs.length > _AVT_MAX_PENDING_INPUTS) {
      ent._pendingInputs.splice(0, ent._pendingInputs.length - _AVT_MAX_PENDING_INPUTS);
    }
    try { RTNet.sendToHost('avt_move_input', { id: ent.id, nome: ent.nome, seq, nx, ny }); } catch(_) {}
    return true;
  }catch(e){
    try{ console.warn('[AVT] _avtEnviarMoveInput falhou:', e); }catch(_){}
    return false;
  }
}
window._avtEnviarMoveInput = _avtEnviarMoveInput;

// Descarta os inputs pendentes de uma entidade (teleporte, troca de fase,
// ressurreição, resync forçado) para evitar reconciliar contra inputs obsoletos.
// IMPORTANTE: o contador `_moveSeq` permanece monotônico — resetá-lo
// dessincronizaria com o `ackSeq` que o host continua incrementando.
function _avtResetMovePredict(ent: any){
  if (!ent) return;
  ent._pendingInputs = [];
}
window._avtResetMovePredict = _avtResetMovePredict;

// Carimbo de atividade REAL de jogo do jogador local (movimento, ação, input).
// Usado por _avtVerificarInatividade para não confundir "jogando sem usar o chat"
// com inatividade — causa do falso "pausado".
function _avtMarcarAtividade(){
  try { (AVT_STATE as any)._ultimaAtividade = Date.now(); } catch(_) {}
}
window._avtMarcarAtividade = _avtMarcarAtividade;

// ── LOOKUP O(1) DE ENTIDADE POR ID ──────────────────────────────────────────
// Substitui os .find(e => e.id === id) dos caminhos quentes (render/handlers).
// O Map é reconstruído no máximo 1x por frame (invalidado por timestamp do frame,
// identidade do array e tamanho), então adds/removes/replaces são cobertos sem
// precisar instrumentar cada ponto de escrita de AVT_STATE.entidades.
function _avtEntById(id: any) {
  if (id == null) return null;
  const st: any = AVT_STATE;
  if (!st || !Array.isArray(st.entidades)) return null;
  const stamp = st._lastFrameTs || 0;
  if (!st._entById || (st as any)._entByIdStamp !== stamp ||
      st._entByIdArr !== st.entidades || (st as any)._entByIdLen !== st.entidades.length) {
    const m = st._entById || ((st as any)._entById = new Map());
    m.clear();
    for (const e of st.entidades) { if (e && e.id != null) m.set(e.id, e); }
    (st as any)._entByIdStamp = stamp;
    (st as any)._entByIdArr = st.entidades;
    (st as any)._entByIdLen = st.entidades.length;
  }
  return st._entById.get(id) || null;
}
window._avtEntById = _avtEntById;

// Chave de sequência escopada por RPG: trocar de aventura sem recarregar a página
// não pode colidir contadores/dedupe de movimento entre salas.
function _avtSeqKey(nomeOuId: any) {
  return ((AVT_STATE && AVT_STATE.rpgId) || '') + '|' + nomeOuId;
}

// ─── SALA DE ESPERA (host voluntário) ──────────────────────────────────────
// Exibe o lobby antes do canvas iniciar. Resolve quando host é eleito.
// callback: função a chamar assim que host_elected disparar.
function _avtSalaEspera(rpgNome: any, callback: any) {
  const rtn = typeof RTNet !== 'undefined' && RTNet.initialized;

  // Se não há RTNet, ou host já eleito (reconexão/reload): inicia diretamente
  if (!rtn) { callback(); return; }
  const jaTemHost = RTNet.isHost() || RTNet.hostId;
  if (jaTemHost) {
    if (!RTNet.isHost() && RTNet.hostId) RTNet.requisitarSnapshot().catch(() => {});
    callback();
    return;
  }

  // Mostra overlay de sala de espera
  const seEl = document.getElementById('avt-sala-espera');
  if (seEl) seEl.style!.display = 'flex';
  const statusEl = document.getElementById('avt-sala-status');
  if (statusEl) statusEl.textContent = '';

  // Atualiza lista de presença periodicamente
  function _atualizarLista() {
    const lista = document.getElementById('avt-sala-lista');
    if (!lista) return;
    const header = '<div style="color:#4fa3d1;margin-bottom:2px;letter-spacing:.05em;font-size:0.6rem;text-transform:uppercase">Jogadores na sala</div>';
    let linhas = header;
    const eu = (typeof SESSION !== 'undefined' && SESSION?.user?.email) || 'Você';
    linhas += `<div style="color:#a8c4d4;padding:2px 0">• ${eu} <span style="color:#7a92aa;font-size:0.58rem">(você)</span></div>`;
    if (rtn && typeof RTNet._peerJoinTs === 'function') {
      for (const [peerId] of RTNet._peerJoinTs()) {
        linhas += `<div style="color:#7a92aa;padding:2px 0">• ${peerId.slice(0, 12)}…</div>`;
      }
    }
    // Diff: só reescreve o DOM quando a lista de fato muda
    if (lista._avtUltimoHtml !== linhas) {
      lista._avtUltimoHtml = linhas;
      lista.innerHTML = linhas;
    }
  }
  _atualizarLista();
  const listInterval = setInterval(_atualizarLista, 2000);

  // Botão "Aguardar Host" apenas desativa ele mesmo e exibe status
  window._avtAguardarSemHost = function() {
    const btn = document.getElementById('avt-btn-aguardar-host');
    if (btn) { btn.disabled = true; btn.style!.opacity = '0.5'; }
    if (statusEl) statusEl.textContent = '⏳ Aguardando host iniciar a sessão…';
  };

  function _onHostChange() {
    clearInterval(listInterval);
    window.removeEventListener('rtnet:hostchange', _onHostChange);
    delete window._avtAguardarSemHost;
    // Re-enable buttons
    const btnHost = document.getElementById('avt-btn-ser-host');
    const btnAguardar = document.getElementById('avt-btn-aguardar-host');
    if (btnHost) { btnHost.disabled = false; btnHost.style!.opacity = ''; }
    if (btnAguardar) { btnAguardar.disabled = false; btnAguardar.style!.opacity = ''; }
    if (!RTNet.isHost()) RTNet.requisitarSnapshot().catch(() => {});
    callback();
  }
  window.addEventListener('rtnet:hostchange', _onHostChange);
}
window._avtSalaEspera = _avtSalaEspera;

// ─── PRNG DETERMINÍSTICO ────────────────────────────────────────────────────
// Todos os clientes na mesma janela de 2s geram o mesmo valor para o mesmo NPC.
// Isso garante que decisões de IA (patrulha, perseguição) sejam idênticas em
// todos os clientes sem precisar de um host dedicado.
function _avtSeededRng(npcId: any, action: any) {
  const tick = Math.floor(Date.now() / 2000);
  let h = 0;
  const s = String(npcId) + action + tick;
  for (let i = 0; i < s.length; i++) { h = Math.imul(31, h) + s.charCodeAt(i) | 0; }
  h ^= h >>> 16; h = Math.imul(h, 0x45d9f3b); h ^= h >>> 16;
  return (h >>> 0) / 0xFFFFFFFF;
}
window._avtSeededRng = _avtSeededRng;

// ─── HP do jogador a partir da fórmula configurada pelo mestre ──────────────
// Fonte única: theme_json.level_config.{hp_base, hp_attr, hp_attr_mult} + custom_attrs.atributos.
// Ignora ch.hp_max persistido — esse campo só guarda snapshots históricos e
// não deve ser usado como teto vivo (o mestre pode rebalancear a qualquer momento).
function _avtCalcHpJog(ch: any) {
  try {
    var lc = (AVT_STATE && AVT_STATE.rpg && AVT_STATE.rpg.theme_json && AVT_STATE.rpg.theme_json.level_config) || {};
    var hpBaseGlobal = lc.hp_base       != null ? lc.hp_base       : 100;
    var hpAttr       = lc.hp_attr       != null ? lc.hp_attr       : 'Constituição';
    var hpAttrMult   = lc.hp_attr_mult  != null ? lc.hp_attr_mult  : 4;
    // Override por personagem: sobrescreve APENAS hp_base; atributo × mult continua aplicado.
    var ovr = ch && ch.custom_attrs && ch.custom_attrs.hp_base_override;
    var hpBase = (ovr != null && ovr !== '' && !isNaN(parseFloat(ovr))) ? parseFloat(ovr) : hpBaseGlobal;
    var atrs = (ch && ch.custom_attrs && ch.custom_attrs.atributos) || {};
    var norm = function(s: any){ return (s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''); };
    var k: any = Object.keys(atrs).find(function(k2){ return norm(k2) === norm(hpAttr); });
    var attrVal = k ? parseFloat(atrs[k] || 0) : 0;
    return Math.max(1, Math.round(hpBase + attrVal * hpAttrMult));
  } catch(e) { return 100; }
}
window._avtCalcHpJog = _avtCalcHpJog;


// Reconcilia AVT_STATE.entidades com AVT_STATE.chars após realtime / reload.
// Atualiza HP, hpMax, nivel e posição persistida (custom_attrs.avt_x/avt_y) sem
// teleportar a entidade controlada localmente.
function _avtReconciliarEntidades(){
  try{
    if(!Array.isArray(AVT_STATE.entidades) || !Array.isArray(AVT_STATE.chars)) return;
    const ctrl = (typeof _avtEntidadeControlada === 'function') ? _avtEntidadeControlada() : null;
    AVT_STATE.chars.forEach((ch: any) => {
      if(!ch || !ch.id) return;
      const ent = AVT_STATE.entidades.find((e: any) => e.dbId === ch.id || e.nome === ch.nome);
      if(!ent) return;
      // hpMax SEMPRE recomputado pela fórmula do mestre (hp_base + attr × mult);
      // ch.hp_max no banco é só snapshot histórico e não é fonte da verdade viva.
      var _hpMaxRec = _avtCalcHpJog(ch);
      ent.hpMax = _hpMaxRec;
      if(typeof ch.hp_atual === 'number') { const _clamped = Math.min(ch.hp_atual, _hpMaxRec); ent.hp = _clamped; if (ch.hp_atual > _hpMaxRec) ch.hp_atual = _clamped; }
      if(typeof ch.nivel    === 'number') ent.nivel = ch.nivel;
      const ca = (ch.custom_attrs && typeof ch.custom_attrs==='object') ? ch.custom_attrs : {};
      if(typeof ca.avt_x === 'number' && typeof ca.avt_y === 'number'){
        if(!ctrl || ctrl.id !== ent.id){
          if(ent.x !== ca.avt_x || ent.y !== ca.avt_y){
            ent.x = ca.avt_x; ent.y = ca.avt_y;
            if(!ent._waypoints || ent._waypoints.length === 0){
              ent.renderX = ca.avt_x; ent.renderY = ca.avt_y;
            }
          }
        }
      }
    });
  }catch(e){ console.warn('[sync] _avtReconciliarEntidades:', e); }
}
window._avtReconciliarEntidades = _avtReconciliarEntidades;

// Re-sync completo após reconexão de WebSocket — chamado por realtime.onopen via
// hook adicional. Re-puxa characters e batalhas, depois reconcilia.
async function _avtResyncEstado(){
  if(!AVT_STATE.rpgId) return;
  try{
    if(typeof sb === 'function'){
      const rows = await sb('characters?rpg_id=eq.' + encodeURIComponent(AVT_STATE.rpgId) + '&select=*');
      if(Array.isArray(rows)){
        AVT_STATE.chars = rows;
        if(typeof RPG_DATA !== 'undefined' && RPG_DATA){ RPG_DATA.characters = rows; }
      }
    }
    if(typeof _avtCarregarBatalhasAtivas === 'function') await _avtCarregarBatalhasAtivas();
    _avtReconciliarEntidades();
  }catch(e){ console.warn('[sync] _avtResyncEstado:', e); }
}
window._avtResyncEstado = _avtResyncEstado;




// ── Skill numbering helpers (per-character ordering) ────────────────────────
// Cada personagem guarda em dbChar.custom_attrs.skill_numeros = { [skId]: n }.
// Skills sem número vão para o fim mantendo a ordem original.
function _avtGetSkillNumero(dbChar: any, ent: any, skId: any) {
  const a = dbChar?.custom_attrs?.skill_numeros;
  const b = ent?.custom_attrs?.skill_numeros;
  const v = (a && a[skId] != null) ? a[skId] : (b && b[skId] != null ? b[skId] : null);
  if (v == null || v === '') return null;
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? n : null;
}
function _avtSkillsOrdenadasPorNumero(skills: any, dbChar: any, ent: any) {
  const arr = (skills || []).slice();
  arr.sort((a: any, b: any) => {
    const na = _avtGetSkillNumero(dbChar, ent, a.id);
    const nb = _avtGetSkillNumero(dbChar, ent, b.id);
    if (na == null && nb == null) return 0;
    if (na == null) return 1;
    if (nb == null) return -1;
    return na - nb;
  });
  return arr;
}
window._avtGetSkillNumero = _avtGetSkillNumero;
window._avtSkillsOrdenadasPorNumero = _avtSkillsOrdenadasPorNumero;
const AVT_T  = { PAREDE: 0, PISO: 1, SAIDA: 2 };
const AVT_SZ = 48;

// Buffer reutilizado para o y-sort do render iso (evita alocar uma cópia por frame).
const _avtYsortBuf: any = [];
// Cache do gradiente radial de atmosfera (luz de tocha). Criado uma vez por raio (SZ),
// na origem; o posicionamento por jogador é feito via ctx.translate no laço de render.
let _avtAtmGrad: any = null, _avtAtmGradR = -1;

// ── SPRITES DE GLOW PRÉ-RENDERIZADOS ─────────────────────────────────────────
// ctx.shadowBlur é uma das operações 2D mais caras (blur gaussiano por chamada);
// nos laços por-entidade-por-frame substituímos por drawImage de um canvas
// offscreen com o glow já pintado. Cache por cor|raio (raio quantizado a 2px para
// limitar variações por zoom); ~poucas dezenas de entradas por sessão.
const _avtGlowCache = new Map();
function _avtGlowSprite(cor: any, raio: any) {
  const r = Math.max(2, Math.round(raio / 2) * 2);
  const key: any = cor + '|' + r;
  let cv = _avtGlowCache.get(key);
  if (!cv) {
    const pad = Math.ceil(r * 0.9);
    const size = (r + pad) * 2;
    cv = document.createElement('canvas');
    cv.width = size; cv.height = size;
    const g = cv.getContext('2d');
    g.shadowColor = cor;
    g.shadowBlur = pad;
    g.fillStyle = cor;
    g.beginPath();
    g.arc(size / 2, size / 2, r, 0, Math.PI * 2);
    g.fill();
    if (_avtGlowCache.size > 96) _avtGlowCache.clear(); // proteção contra crescimento
    _avtGlowCache.set(key, cv);
  }
  return cv;
}
// Desenha o glow cacheado centrado em (cx, cy) com a opacidade dada.
function _avtGlowDraw(ctx: any, cor: any, raio: any, cx: any, cy: any, alpha: any) {
  const cv = _avtGlowSprite(cor, raio);
  const prev = ctx.globalAlpha;
  if (alpha != null) ctx.globalAlpha = prev * alpha;
  ctx.drawImage(cv, cx - cv.width / 2, cy - cv.height / 2);
  if (alpha != null) ctx.globalAlpha = prev;
}
// Poda simples de caches objeto-por-URL (evita crescimento sem limite ao longo
// de uma sessão longa com muitas fases/imagens). Remove os inseridos há mais
// tempo (ordem de inserção das chaves string).
function _avtCachePrune(obj: any, max: any) {
  const keys = Object.keys(obj);
  if (keys.length <= max) return;
  const remover = keys.length - max;
  for (let i = 0; i < remover; i++) delete obj[keys[i]];
}

// Gradiente radial cacheado na origem (posicionar via ctx.translate).
// stops: [[offset, cor], ...] — a chave inclui os stops serializados.
const _avtRadGradCache = new Map();
function _avtRadGrad(ctx: any, r0: any, r1: any, stops: any) {
  const key: any = r0 + '|' + r1 + '|' + stops.map((s: any) => s[0] + s[1]).join(',');
  let g = _avtRadGradCache.get(key);
  if (!g) {
    g = ctx.createRadialGradient(0, 0, r0, 0, 0, r1);
    for (const [off, cor] of stops) g.addColorStop(off, cor);
    if (_avtRadGradCache.size > 96) _avtRadGradCache.clear();
    _avtRadGradCache.set(key, g);
  }
  return g;
}

// ── Cores dos efeitos de status (usados em visuais de canvas e CSS) ──────────
const AVT_STATUS_COLORS: Record<string, any> = {
  stun:         '#9b59b6',
  silence:      '#1a0028',
  dot:          '#c0392b',
  hot:          '#2ecc71',
  atravessar:   '#3498db',
  cura:         '#27ae60',
  boost_dano:   '#f0cc6a',
  mod_dano:     '#e8604c',
  sem_movimento:'#c0392b',
  sem_ataque:   '#e67e22',
  esquiva:      '#74b9ff',
  rec:          '#b07ef0',
  rec_atributo: '#b07ef0',
  imune_dano:   '#74b9ff',
  ab_cd_reduzir:   '#f39c12',
  ab_dano_buff:    '#f0cc6a',
  ab_multi_alvo:   '#e67e22',
  ab_alcance_buff: '#27ae60',
  fantasma:     '#74b9ff',
  teleporte:    '#a29bfe',
  invocacao:    '#b07ef0',
  necromante:   '#8e44ad',
  rastro_persona: '#5ee09a',
  rastro_anima:   '#5ee09a',
};

function _avtHexRgb(hex: any) {
  if (!hex || hex.length < 7) return '122,146,170';
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `${r},${g},${b}`;
}

// Normaliza efeitos_bonus autorados no editor para o formato canônico do
// registry (um objeto por tipo, com `tipo` e `duracao_turnos` definidos).
// O editor combina vários componentes num objeto só e usa campos de duração
// próprios (dot_turnos, boost_dano_turnos, …) que o runtime não lê — sem esta
// normalização, DOT/HOT autorados expiram em 1 turno e buffs como boost_dano
// nunca são reconhecidos pelo tick. Idempotente (marca _canonico).
function _avtNormalizarEfeitosSkill(efeitos: any) {
  if (!Array.isArray(efeitos) || !efeitos.length) return efeitos || [];
  if (typeof EFFECT_REGISTRY === 'undefined') return efeitos;
  try { return EFFECT_REGISTRY.normalizarEfeitos(efeitos); } catch(_) { return efeitos; }
}

// Agrega buffs/debuffs de combate ativos em status_effects de uma entidade.
// boost_dano/mod_dano modificam o dano CAUSADO pela entidade (aditivos);
// imune_dano zera o dano RECEBIDO enquanto ativo. Estes campos eram gravados
// em status_effects mas nunca lidos no modo aventura.
function _avtBuffsCombateEnt(ent: any) {
  const out = { boostDano: 0, modDano: 0, imune: false };
  if (!ent?.status_effects?.length) return out;
  const now = Date.now();
  ent.status_effects.forEach((ef: any) => {
    const ativo = ef._ooc
      ? (!ef.expiry_ms || now < ef.expiry_ms)
      : (ef._turnos_restantes ?? 0) > 0;
    if (!ativo) return;
    if (ef.tipo === 'boost_dano' || (ef.boost_dano != null && ef.tipo == null)) out.boostDano += Number(ef.boost_dano) || 0;
    if (ef.tipo === 'mod_dano'   || (ef.mod_dano   != null && ef.tipo == null)) out.modDano   += Number(ef.mod_dano)   || 0;
    if (ef.tipo === 'imune_dano' || ef.imune_dano) out.imune = true;
  });
  return out;
}

// Dano de saída com buffs da entidade aplicados (nunca abaixo de 0).
function _avtAplicarBuffsDanoSaida(ent: any, dano: any) {
  const b = _avtBuffsCombateEnt(ent);
  const mod = b.boostDano + b.modDano;
  if (!mod) return dano;
  return Math.max(0, dano + mod);
}

// Dano de entrada considerando imunidade do defensor. Retorna o dano final.
function _avtAplicarImunidadeDano(ent: any, dano: any) {
  if (dano <= 0) return dano;
  if (!_avtBuffsCombateEnt(ent).imune) return dano;
  try { mostrarToast(`🛡 ${ent.nome} está imune a dano!`, '', 1800); } catch(_) {}
  return 0;
}

// Tipos de efeito que entram em status_effects, derivados do registry central —
// um efeito novo registrado em effect-registry.js entra automaticamente em todos
// os caminhos de aplicação que usam esta lista. `opts.positivos` filtra por
// polaridade (aliados só recebem positivos); `extras` preserva tipos com fluxo
// próprio que historicamente entram em status_effects num caminho específico.
function _avtStatusTipos(opts = {}, extras: any = []) {
  let base = ['dot', 'hot', 'stun', 'silence', 'fantasma', 'atravessar'];
  if (typeof EFFECT_REGISTRY !== 'undefined') {
    try { base = EFFECT_REGISTRY.statusTipos(opts); } catch(_) {}
  }
  // Necromante tem gatilho próprio (dominação na morte) — nunca entra genérico.
  base = base.filter(t => t !== 'necromante');
  return extras.length ? base.concat(extras) : base;
}

// Tick de rec_atributo: recupera o recurso configurado no personagem-jogador
// (rec_atributo vazio = primeiro recurso; ex.: orbe de efeito). Mesma persistência
// do pickup de orbe de mana (custom_attrs.atributos + avt_rsv_update).
function _avtAplicarRecAtributo(ent: any, ef: any) {
  if (!ent || ent.tipo !== 'jogador') return;
  const char = AVT_STATE.chars.find((c: any) => c.nome === ent.nome || c.id === ent.dbId);
  if (!char) return;
  const recursos = _avtRecursosDoChar(char);
  if (!recursos?.length) return;
  const alvoNome = (ef.rec_atributo || '').trim();
  const rec = alvoNome
    ? recursos.find((r: any) => r.nome.toLowerCase() === alvoNome.toLowerCase())
    : (recursos.find((r: any) => /mana/i.test(r.nome)) || recursos[0]);
  if (!rec) return;
  const rolado = _avtRolarFormula(ef.rec_formula || '5');
  const add = ef.rec_modo === 'pct' ? Math.round(rec.max * rolado / 100) : rolado;
  if (add <= 0) return;
  const novo = Math.min(rec.max, rec.atual + add);
  if (novo === rec.atual) return;
  if (!char.custom_attrs) char.custom_attrs = {};
  const atrs = char.custom_attrs.atributos || (char.custom_attrs.atributos = {});
  atrs[rec.nome] = novo;
  _avtSb(`characters?id=eq.${encodeURIComponent(char.id)}`, {
    method: 'PATCH', body: JSON.stringify({ custom_attrs: char.custom_attrs })
  }).catch(() => {});
  try { _avtBroadcast('avt_rsv_update', { nome: ent.nome, atributos: { ...atrs } }); } catch(_) {}
  try { mostrarToast(`🔋 +${add} ${rec.nome}`, '', 1500); } catch(_) {}
}

function _avtEfetosAtivosEnt(ent: any) {
  if (!ent) return [];
  const results: any = [];
  const seen = new Set();
  const now = Date.now();

  (ent.status_effects || []).forEach((ef: any) => {
    if ((ef._turnos_restantes ?? 0) <= 0) return;
    // Efeitos OOC vivem em _oocStatusEffects com expiry_ms (mostra segundos).
    // Fora de combate: pular aqui para não mascarar a entrada correta abaixo.
    // Em combate: _turnos_restantes é decrementado pelo sistema → mostrar como turno.
    let _inBat = false;
    try { _inBat = !!_avtBatalhaDeEnt(ent.id); } catch(_) {}
    if (ef._ooc && !_inBat) return;
    if (seen.has(ef.tipo)) return;
    seen.add(ef.tipo);
    results.push({
      tipo:  ef.tipo,
      nome:  ef.nome || ef.tipo,
      cor:   ef.cor || AVT_STATUS_COLORS[ef.tipo] || '#7a92aa',
      // Orbe por cargas: mostra "n⚡" (skills restantes) em vez de turnos
      label: ef._cargas_restantes != null ? `${ef._cargas_restantes}⚡` : String(ef._turnos_restantes),
      isOoc: false,
    });
  });

  (AVT_STATE._oocStatusEffects || [])
    .filter((r: any) => (r.entId === ent.id || (ent.nome && r.entNome === ent.nome)) && now < r.ef.expiry_ms)
    .forEach((r: any) => {
      const ef = r.ef;
      if (seen.has(ef.tipo)) return;
      seen.add(ef.tipo);
      const secsLeft = Math.max(1, Math.ceil((ef.expiry_ms - now) / 1000));
      results.push({
        tipo:  ef.tipo,
        nome:  ef.nome || ef.tipo,
        cor:   ef.cor || AVT_STATUS_COLORS[ef.tipo] || '#7a92aa',
        // Orbe por cargas: mostra "n⚡" (skills restantes) em vez de segundos
        label: ef._cargas_restantes != null ? `${ef._cargas_restantes}⚡` : secsLeft + 's',
        isOoc: true,
      });
    });

  return results;
}

// ══ Rastros contaminados (Rastro Persona / Rastro Anima) ═════════════════════
// Células contaminadas que causam dano a inimigos que passarem por elas. Cada célula
// fere cada inimigo apenas 1× (hitSet). Vivem em AVT_STATE._rastroCells.

// Autoridade do estado autoritativo: host eleito ou sessão sem RTNet (solo/legado).
// Mesma condição usada para o tick OOC em _avtRenderFrame.
function _avtEhAutoridade() {
  return typeof RTNet === 'undefined' || !RTNet.initialized || RTNet.isHost();
}
window._avtEhAutoridade = _avtEhAutoridade;

// [4.4] Define um cooldown OOC e propaga em tempo real (sem esperar o snapshot de 15s).
function _avtSetOocCooldown(key: any, expiry: any) {
  if (!key) return;
  AVT_STATE._oocCooldowns = AVT_STATE._oocCooldowns || {};
  AVT_STATE._oocCooldowns[key] = expiry;
  try { _avtBroadcast('avt_ooc_cooldown', { key, expiry }); } catch(_) {}
}
window._avtSetOocCooldown = _avtSetOocCooldown;

// Marca uma célula como contaminada pelo caster. Mescla células iguais do mesmo caster.
// `_fromNet`: quando true, a célula veio de avt_rastro_marcar (não re-broadcasta) e usa
// o `expiry_ms` recebido para manter a expiração idêntica entre clientes.
function _avtRastroMarcarCelula(caster: any, x: any, y: any, formula: any, duracaoTurnos: any, cor: any, _fromNet?: any, _expiryMs?: any) {
  if (!caster || formula == null) return;
  const tx = Math.round(x), ty = Math.round(y);
  if (typeof _avtTilePassavel === 'function' && !_avtTilePassavel(tx, ty, AVT_STATE.dungeon)) return;
  if (!AVT_STATE._rastroCells) (AVT_STATE as any)._rastroCells = [];
  const dur = Math.max(1, duracaoTurnos || 3);
  const corCel = cor || '#5ee09a';
  const expiry = (_fromNet && typeof _expiryMs === 'number') ? _expiryMs : (Date.now() + dur * _avtGetEfeitoCooldownMs());
  const casterNome = typeof caster === 'string' ? caster : caster.nome;
  const casterId = typeof caster === 'object' ? (caster.id || null) : null;
  // Propaga a contaminação a todos os clientes (rastro é renderizado por todos; o dano
  // é aplicado só pela autoridade — ver _avtRastroChecarEntrada).
  if (!_fromNet) {
    try { _avtBroadcast('avt_rastro_marcar', { x: tx, y: ty, formula, expiry_ms: expiry, caster: casterNome, casterId, cor: corCel, duracaoTurnos: dur }); } catch(_) {}
  }
  const ex = (AVT_STATE as any)._rastroCells.find((c: any) => c.x === tx && c.y === ty && c.caster === casterNome);
  if (ex) { ex.expiry_ms = Math.max(ex.expiry_ms, expiry); ex.formula = formula; ex.cor = corCel; return; }
  (AVT_STATE as any)._rastroCells.push({ x: tx, y: ty, formula, expiry_ms: expiry, caster: casterNome, casterId, cor: corCel, hitSet: new Set() });
}

// Predicado: entidade hostil ao jogador (inimigo ou invocação inimiga; nunca jogador/aliado/dominado/invocação do jogador)
function _avtRastroEhHostil(e: any) {
  if (!e || e.hp <= 0 || e.escondido || e._dominado) return false;
  if (e.tipo === 'inimigo') return true;
  if (e.tipo === 'invocado') return !(AVT_STATE.invocacoes_ativas || []).some((i: any) => i.id === e.id);
  return false;
}

// Aplica dano de rastro quando uma entidade hostil entra/está numa célula contaminada.
function _avtRastroChecarEntrada(ent: any, x: any, y: any) {
  // Dano de rastro é autoritativo: apenas o host aplica (e propaga via avt_hp_update).
  // Não-host renderiza as células, mas não aplica dano — evita HP não-autoritativo
  // revertido pelo tick.
  if (!_avtEhAutoridade()) return;
  const cells = (AVT_STATE as any)._rastroCells;
  if (!cells || !cells.length || !_avtRastroEhHostil(ent)) return;
  const tx = Math.round(x), ty = Math.round(y), now = Date.now();
  for (const cell of cells) {
    if (now >= cell.expiry_ms || cell.x !== tx || cell.y !== ty) continue;
    if (cell.hitSet.has(ent.id)) continue;
    cell.hitSet.add(ent.id);
    const dano = _avtRolarFormula(cell.formula || '1d6');
    if (dano <= 0) continue;
    ent.hp = Math.max(0, ent.hp - dano);
    try { _avtAplicarDanoPersistir(ent, ent.hp); } catch(_) {}
    try { _avtMostrarDanoAbaixoHp(ent, dano, false); } catch(_) {}
    try { _avtMostrarDotDrip(ent, 'contaminacao'); } catch(_) {}
    try { _avtBroadcast('avt_hp_update', { nome: ent.nome, hp: ent.hp, hpMax: ent.hpMax }); } catch(_) {}
    const _batR = (typeof _avtBatalhaDeEnt === 'function') ? _avtBatalhaDeEnt(ent.id) : null;
    _avtLog(`🟢 ${ent.nome} sofre ${dano} de rastro contaminado`, _batR?.id);
    if (ent.hp <= 0) { _avtNpcMorreu(ent, _batR || null, { creditoNome: cell.caster }); if (_batR) _avtCheckVitoria(_batR); }
  }
}

// Células de uma trajetória reta (Bresenham inteiro) entre dois tiles.
function _avtRastroCelulasTrajetoria(ax: any, ay: any, bx: any, by: any) {
  ax = Math.round(ax); ay = Math.round(ay); bx = Math.round(bx); by = Math.round(by);
  const cells = [];
  const dx = Math.abs(bx - ax), dy = Math.abs(by - ay);
  const sx = ax < bx ? 1 : -1, sy = ay < by ? 1 : -1;
  let err = dx - dy, x = ax, y = ay, guard = 0;
  while (guard++ < 256) {
    cells.push({ x, y });
    if (x === bx && y === by) break;
    const e2 = 2 * err;
    if (e2 > -dy) { err -= dy; x += sx; }
    if (e2 <  dx) { err += dx; y += sy; }
  }
  return cells;
}

// Efeito rastro_persona ativo no caster (para marcar células durante o movimento).
function _avtRastroPersonaAtivo(ent: any) {
  if (!ent || !ent.status_effects) return null;
  const now = Date.now();
  return ent.status_effects.find((e: any) => e.tipo === 'rastro_persona' &&
    (e._turnos_restantes ?? 0) > 0 && (!e.expiry_ms || now < e.expiry_ms)) || null;
}

// Aplica um efeito de rastro no momento do lançamento da skill (no caster).
function _avtAplicarRastroEfeito(ef: any, casterEnt: any, alvoEnt: any) {
  if (!casterEnt || !ef) return;
  const dur = ef.duracao_turnos ?? 3;
  const formula = ef.rastro_formula || '1d6';
  const cor = ef.rastro_cor || '#5ee09a';
  if (ef.tipo === 'rastro_persona') {
    // Buff no caster: enquanto ativo, células pisadas ficam contaminadas
    if (!casterEnt.status_effects) casterEnt.status_effects = [];
    if (!casterEnt.status_effects.some((e: any) => e.tipo === 'rastro_persona' && (e._turnos_restantes ?? 0) > 0)) {
      const inBat = (typeof _avtBatalhaDeEnt === 'function') && !!_avtBatalhaDeEnt(casterEnt.id);
      const entry = { ...ef, nome: ef.nome || 'Rastro Persona', _turnos_restantes: dur,
        expiry_ms: Date.now() + dur * _avtGetEfeitoCooldownMs() };
      if (!inBat) entry._ooc = true;
      casterEnt.status_effects.push(entry);
      if (!inBat) (AVT_STATE._oocStatusEffects = AVT_STATE._oocStatusEffects || []).push({ entId: casterEnt.id, entNome: casterEnt.nome, ef: { ...entry }, lastTickAt: Date.now() });
      // Animação persistente do buff Rastro Persona segue o conjurador durante a duração.
      _avtIniciarAnimPersistente(entry, casterEnt, casterEnt);
    }
    _avtRastroMarcarCelula(casterEnt, casterEnt.x, casterEnt.y, formula, dur, cor);
  } else if (ef.tipo === 'rastro_anima') {
    if (alvoEnt) {
      _avtRastroCelulasTrajetoria(casterEnt.x, casterEnt.y, alvoEnt.x, alvoEnt.y)
        .forEach(c => _avtRastroMarcarCelula(casterEnt, c.x, c.y, formula, dur, cor));
    }
  }
}

// Aplica empurrão/puxão (forced movement) a um alvo no momento do efeito.
// `empurrao_direcao`: 'longe' = afasta o alvo do conjurador; 'perto' = puxa em direção a ele.
// `empurrao_distancia`: nº máximo de células deslocadas; para em parede ou célula ocupada.
// Espelha js/maps/maps.js → mapaForcedMovement, adaptado às coordenadas da aventura.
function _avtAplicarEmpurrao(ef: any, casterEnt: any, alvoEnt: any, bat: any) {
  if (!casterEnt || !alvoEnt || !ef || alvoEnt.hp <= 0) return;
  const distancia = Math.max(1, parseInt(ef.empurrao_distancia) || 3);
  const direcao   = ef.empurrao_direcao === 'perto' ? 'perto' : 'longe';
  const dxRaw = Math.round(alvoEnt.x) - Math.round(casterEnt.x);
  const dyRaw = Math.round(alvoEnt.y) - Math.round(casterEnt.y);
  let dc = Math.sign(dxRaw), dr = Math.sign(dyRaw);
  if (direcao === 'perto') { dc = -dc; dr = -dr; }
  if (dc === 0 && dr === 0) return; // mesma célula — direção indefinida

  let x = Math.round(alvoEnt.x), y = Math.round(alvoEnt.y);
  let passos = 0, bateu = false;
  for (let i = 0; i < distancia; i++) {
    const nx = x + dc, ny = y + dr;
    const passavel = (typeof _avtTilePassavel !== 'function') || _avtTilePassavel(nx, ny, AVT_STATE.dungeon);
    const ocupada  = (typeof _avtCelulaOcupada === 'function') && _avtCelulaOcupada(nx, ny, alvoEnt.id, alvoEnt.tipo, false);
    if (!passavel || ocupada) { bateu = true; break; }
    x = nx; y = ny; passos++;
  }

  if (passos > 0) {
    alvoEnt.x = x; alvoEnt.y = y;
    const _ini = bat?.iniciativa?.find((e: any) => e.id === alvoEnt.id);
    if (_ini) { _ini.x = x; _ini.y = y; }
    const _entObj = AVT_STATE.entidades.find((e: any) => e.id === alvoEnt.id);
    if (_entObj && _entObj !== alvoEnt) { _entObj.x = x; _entObj.y = y; }
    try { _avtBcastTokenMove({ nome: alvoEnt.nome, x, y }); } catch(_) {}
    const _lbl = direcao === 'longe' ? 'empurrado' : 'puxado';
    _avtLog(`💨 ${alvoEnt.nome} foi ${_lbl} ${passos} célula(s)`, bat?.id);
  }

  // Dano de impacto ao colidir com obstáculo. Aplicado pelo cliente que resolve a ação
  // (mesmo padrão do dano direto de ataque, ex.: L12400/8729) — não é gated por host.
  if (bateu) {
    const danoImpacto = _avtRolarFormula(ef.empurrao_dano_impacto || '1d6');
    if (alvoEnt.tipo === 'jogador') {
      try { _avtRTBroadcastPlayerDamage(alvoEnt.nome, danoImpacto, casterEnt.nome); } catch(_) {}
      try { _avtMostrarDanoAbaixoHp(alvoEnt, danoImpacto, false); } catch(_) {}
      if (bat) _avtCheckDerrota(bat);
    } else {
      alvoEnt.hp = Math.max(0, alvoEnt.hp - danoImpacto);
      const _entObj2 = AVT_STATE.entidades.find((e: any) => e.id === alvoEnt.id);
      if (_entObj2 && _entObj2 !== alvoEnt) _entObj2.hp = alvoEnt.hp;
      const _ini2 = bat?.iniciativa?.find((e: any) => e.id === alvoEnt.id);
      if (_ini2) _ini2.hp = alvoEnt.hp;
      try { _avtAplicarDanoPersistir(_entObj2 || alvoEnt, alvoEnt.hp); } catch(_) {}
      try { _avtMostrarDanoAbaixoHp(_entObj2 || alvoEnt, danoImpacto, false); } catch(_) {}
      try { _avtBroadcast('avt_hp_update', { nome: alvoEnt.nome, hp: alvoEnt.hp, hpMax: alvoEnt.hpMax }); } catch(_) {}
      if (alvoEnt.hp <= 0 && alvoEnt.tipo === 'inimigo') {
        _avtNpcMorreu(_entObj2 || alvoEnt, bat || null, { creditoNome: casterEnt.nome });
        if (bat) _avtCheckVitoria(bat);
      }
    }
    _avtLog(`  ↳ ${alvoEnt.nome} colidiu e sofreu ${danoImpacto} de impacto`, bat?.id);
  }
  try { _avtRenderHpBar(); } catch(_) {}
}
window._avtAplicarEmpurrao = _avtAplicarEmpurrao;

// Remove células de rastro expiradas (chamado periodicamente).
function _avtRastroPrune() {
  if (!AVT_STATE._rastroCells || !(AVT_STATE as any)._rastroCells.length) return;
  const now = Date.now();
  AVT_STATE._rastroCells = (AVT_STATE as any)._rastroCells.filter((c: any) => now < c.expiry_ms);
}

// Recebe contaminação de rastro de outro cliente e recria a célula localmente.
window.avtReceberRastroMarcar = function(p: any) {
  try {
    if (!p || typeof p.x !== 'number' || typeof p.y !== 'number') return;
    if (!_avtMinhaFase(p.faseId)) return; // isolamento por fase (F2)
    if (p.expiry_ms && Date.now() >= p.expiry_ms) return; // já expirada
    _avtRastroMarcarCelula(p.caster || p.casterId, p.x, p.y, p.formula, p.duracaoTurnos || 3, p.cor, true, p.expiry_ms);
  } catch(_) {}
};

// [4.4] Recebe um cooldown OOC de outro cliente (aplicação monotônica, ignora expirados).
window.avtReceberOocCooldown = function(p: any) {
  try {
    if (!p || !p.key || typeof p.expiry !== 'number') return;
    if (p.expiry <= Date.now()) return;
    AVT_STATE._oocCooldowns = AVT_STATE._oocCooldowns || {};
    const atual = AVT_STATE._oocCooldowns[p.key] || 0;
    if (p.expiry > atual) AVT_STATE._oocCooldowns[p.key] = p.expiry;
    try { if (typeof _avtRenderHpBar === 'function') _avtRenderHpBar(); } catch(_) {}
  } catch(_) {}
};

// [4.6] Inventário mudou em outro cliente: recarrega do banco (fonte da verdade) e
// re-renderiza qualquer painel/HUD aberto daquele personagem. `ouro` (opcional) é
// aplicado direto, pois vive em characters.custom_attrs (não na tabela inventario).
window.avtReceberInvUpdate = async function(p: any) {
  try {
    if (!p || !p.charId) return;
    const charId = String(p.charId);
    const char = (AVT_STATE.chars || []).find((c: any) => String(c.id) === charId);
    if (typeof p.ouro === 'number' && char) {
      char.custom_attrs = char.custom_attrs || {};
      char.custom_attrs.ouro = p.ouro;
    }
    if (typeof avtInvCarregarChar === 'function') { try { await avtInvCarregarChar(charId); } catch(_) {} }
    // Re-render: painel/HUD do jogador local e modais de inventário abertos.
    const charNome = char?.nome || null;
    try { if (typeof avtJogadorPainelRender === 'function') avtJogadorPainelRender(); } catch(_) {}
    try {
      const modal = document.getElementById('avt-inventario-modal');
      if (modal && modal.style!.display !== 'none' && charNome && typeof avtInvRenderPanel === 'function') {
        avtInvRenderPanel(charNome, 'avt-inv-body');
      }
    } catch(_) {}
    // O inventário do mestre é parte do painel do mestre — re-renderiza se aberto.
    try { if (typeof _avtMestrePainelRender === 'function') _avtMestrePainelRender(); } catch(_) {}
  } catch(_) {}
};

// Desenha as células contaminadas no grid (pulso translúcido).
function _avtRenderRastroCells(ctx: any, camera: any, SZ: any, canvas: any) {
  const cells = (AVT_STATE as any)._rastroCells;
  if (!cells || !cells.length) return;
  const now = Date.now();
  const pulse = 0.10 + 0.06 * (0.5 + 0.5 * Math.sin(now / 350));
  for (const cell of cells) {
    if (now >= cell.expiry_ms) continue;
    const px = Math.round(cell.x * SZ - camera.x);
    const py = Math.round(cell.y * SZ - camera.y);
    if (px + SZ < 0 || px > canvas.width || py + SZ < 0 || py > canvas.height) continue;
    const rgb = _avtHexRgb(cell.cor || '#5ee09a');
    ctx.fillStyle = `rgba(${rgb},${pulse.toFixed(3)})`;
    ctx.fillRect(px, py, SZ, SZ);
    ctx.strokeStyle = `rgba(${rgb},0.5)`;
    ctx.lineWidth = 1;
    ctx.strokeRect(px + 1.5, py + 1.5, SZ - 3, SZ - 3);
  }
}

