const _avtClasseImgCache: Record<string, any> = {};
function _avtGetClasseImg(classeAventura: any, variant: any, modo: any) {
  const sfx = (modo === 'head') ? '_HEAD' : '';
  const key: any = `${classeAventura}_${variant}${sfx}`;
  if (_avtClasseImgCache[key]) return _avtClasseImgCache[key];
  const svgMap: Record<string, any> = {
    guerreiro_0: AVT_WARRIOR_SVG_A,  guerreiro_1: AVT_WARRIOR_SVG_B,
    guerreiro_0_HEAD: AVT_WARRIOR_SVG_A_HEAD, guerreiro_1_HEAD: AVT_WARRIOR_SVG_B_HEAD,
    mago_0: AVT_MAGE_SVG_A,          mago_1: AVT_MAGE_SVG_B,
    mago_0_HEAD: AVT_MAGE_SVG_A_HEAD,         mago_1_HEAD: AVT_MAGE_SVG_B_HEAD,
    paladino_0: AVT_PALADIN_SVG_A,   paladino_1: AVT_PALADIN_SVG_B,
    paladino_0_HEAD: AVT_PALADIN_SVG_A_HEAD,   paladino_1_HEAD: AVT_PALADIN_SVG_B_HEAD,
    arqueiro_0: AVT_ARCHER_SVG_A,    arqueiro_1: AVT_ARCHER_SVG_B,
    arqueiro_0_HEAD: AVT_ARCHER_SVG_A_HEAD,    arqueiro_1_HEAD: AVT_ARCHER_SVG_B_HEAD,
    ladino_0: AVT_LADINO_SVG_A,      ladino_1: AVT_LADINO_SVG_B,
    ladino_0_HEAD: AVT_LADINO_SVG_A_HEAD,      ladino_1_HEAD: AVT_LADINO_SVG_B_HEAD,
  };
  const svgStr = svgMap[key] || svgMap[`${classeAventura}_${variant}`];
  if (!svgStr) return null;
  const img = new Image();
  img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svgStr);
  _avtClasseImgCache[key] = img;
  return img;
}
function _avtClasseVariant(nome: any) {
  let h = 0;
  for (let i = 0; i < (nome || '').length; i++) h = (h * 31 + nome.charCodeAt(i)) & 0xffff;
  return h % 2;
}

// Prompts para token top-down IA
const AVT_TOPDOWN_GEN_PROMPT = (desc: any) => `Crie um token RPG top-down (visão de cima, bird's-eye view) para: ${desc || 'um personagem RPG'}.
Estilo: pixel art ou pintado à mão, fundo TRANSPARENTE (PNG).
Resolução: qualquer — o engine reescala proporcionalmente. Prefira imagem aproximadamente quadrada (1:1) com o personagem centralizado e ocupando boa parte do quadro.
Perspectiva: estritamente top-down — câmera diretamente acima do personagem.
Mostre: topo da cabeça (cabelo/capacete), ombros, arma/equipamento segurado para o lado, pés levemente visíveis.
Silhueta clara e legível mesmo quando reduzida (o token será exibido pequeno no mapa).
SEM fundo, SEM sombra projetada (será adicionada pelo engine).
Use cores adequadas para um personagem de RPG.`;

// Prompt para gerar o SPRITE ISOMÉTRICO (figura em pé, vista 3/4) usado na visão iso.
const AVT_ISO_GEN_PROMPT = (desc: any) => `Crie um sprite isométrico de RPG (vista 3/4, ~45°, como Diablo) para: ${desc || 'um personagem RPG'}.
Estilo: pixel art ou pintado à mão, fundo TRANSPARENTE (PNG, canal alpha).
Enquadramento: corpo INTEIRO de pé, de frente para a câmera em leve perspectiva 3/4.
MUITO IMPORTANTE — para o engine animar e plantar no tile:
• Os PÉS devem ficar na BASE-CENTRO da imagem (rente à borda inferior, horizontalmente centralizados).
• Figura vertical "em pé"; a imagem deve ser mais alta do que larga (ex.: proporção ~3:4 ou 2:3).
• Personagem centralizado horizontalmente, ocupando boa parte da altura do quadro.
SEM fundo, SEM sombra projetada e SEM moldura (a sombra é adicionada pelo engine).
Silhueta legível mesmo reduzido. Cores adequadas a um personagem de RPG.`;

const AVT_TOPDOWN_COORD_PROMPT = `Analise esta imagem de token RPG vista de cima (top-down, bird's-eye view, fundo transparente) e retorne APENAS JSON (sem markdown, sem blocos de código — apenas o objeto JSON começando com {) com as coordenadas normalizadas (0.0–1.0) das regiões visuais para animação.

{
  "body_cx": 0.50,
  "body_cy": 0.55,
  "body_r":  0.30,
  "head_cx": 0.50,
  "head_cy": 0.28,
  "head_r":  0.18,
  "weapon_cx": 0.72,
  "weapon_cy": 0.60,
  "weapon_r":  0.10,
  "legs_cy":   0.75,
  "legs_r":    0.12,
  "shadow_y":  0.88,
  "pivot_x":   0.50,
  "pivot_y":   0.50
}

REGRAS:
- x=0=esquerda, x=1=direita, y=0=topo, y=1=base.
- body_cx/cy: centro do corpo/torso visto de cima.
- body_r: raio do corpo como fração da largura da imagem.
- head_cx/cy: centro da cabeça (topo da figura).
- head_r: raio da cabeça.
- weapon_cx/cy: centro da arma ou membro estendido (0.5/0.5 se não visível).
- weapon_r: tamanho do elemento arma (0 se ausente).
- legs_cy: y da região de pernas/base.
- legs_r: raio da região de pernas.
- shadow_y: y onde a sombra tocaria o chão (geralmente 0.85–0.95).
- pivot_x/y: ponto de rotação do token para animação.`;

